                !LinuxText(state, " pages=") || !LinuxNumber(state, state->LinuxPages) || !LinuxText(state, " handlesClosed=2 reads=") || !LinuxNumber(state, state->LinuxReadCalls) || !LinuxText(state, "\r\nM16_002_DIGEST ")) return false;
