#if M03_FIRMWARE_ENTROPY_SEED_PROBE || M16_004_PROBE
    // One pre-EBS acquisition. The host Span/interface contract is deliberately
    // separate; this EFI boundary has only numeric values and admitted pointers.
    internal static class FirmwareEntropyCapture
    {
        internal const ulong RequestedBytes = 32;
        internal const ulong PayloadBytes = 64;
        internal const ulong NotFound = 0x800000000000000EUL;
        private const ulong Guard0 = 0x39D18A675BE024CFUL;
        private const ulong Guard1 = 0xE62740BC951ADF38UL;
        internal unsafe struct Buffer
        {
            internal ulong Before0, Before1;
            internal fixed byte Data[64];
            internal ulong After0, After1;
        }
        internal unsafe struct Protocol
        {
            internal void* GetInfo;
            internal delegate* unmanaged<Protocol*, EfiGuid*, nuint, byte*, ulong> GetRng;
        }
        internal unsafe struct State
        {
            internal ulong Phase, Error, PublishedBytes;
            internal EfiSystemTable* SystemTable;
            internal EfiBootServices* BootServices;
            internal delegate* unmanaged<EfiGuid*, void*, void**, ulong> Locate;
            internal Protocol* Rng;
            internal delegate* unmanaged<Protocol*, EfiGuid*, nuint, byte*, ulong> GetRng;
            internal Buffer* Scratch;
            internal Buffer* Retained;
            internal ulong LocateCalls, LocateStatus, RngCalls, RngStatus;
        }
        private static State s_state;
        private static Buffer s_scratch, s_retained;

        private static bool Span(ulong start, ulong length, ulong alignment) =>
            start != 0 && (start & (alignment - 1)) == 0 &&
            length != 0 && start <= ulong.MaxValue - length;
        private static bool Apart(ulong a, ulong an, ulong b, ulong bn) =>
            a + an <= b || b + bn <= a;
        private static bool Excluded(ulong p, ulong n, State* s, Buffer* scratch, Buffer* retained) =>
            Apart(p, n, (ulong)s, (ulong)sizeof(State)) &&
            Apart(p, n, (ulong)scratch, (ulong)sizeof(Buffer)) &&
            Apart(p, n, (ulong)retained, (ulong)sizeof(Buffer));

        // The firmware-owned tables must be genuine caller-provided readable
        // storage. Numeric admission rejects malformed extents; it is not a
        // mapping oracle for arbitrary addresses supplied by an attacker.
        internal static bool Begin(State* s, Buffer* scratch, Buffer* retained, EfiSystemTable* table)
        {
            if (!Span((ulong)s, (ulong)sizeof(State), 8) ||
                !Span((ulong)scratch, (ulong)sizeof(Buffer), 8) ||
                !Span((ulong)retained, (ulong)sizeof(Buffer), 8) ||
                !Span((ulong)table, (ulong)sizeof(EfiSystemTable), 8) ||
                !Apart((ulong)s, (ulong)sizeof(State), (ulong)scratch, (ulong)sizeof(Buffer)) ||
                !Apart((ulong)s, (ulong)sizeof(State), (ulong)retained, (ulong)sizeof(Buffer)) ||
                !Apart((ulong)scratch, (ulong)sizeof(Buffer), (ulong)retained, (ulong)sizeof(Buffer)) ||
                !Excluded((ulong)table, (ulong)sizeof(EfiSystemTable), s, scratch, retained)) return false;
            EfiBootServices* services = table->BootServices;
            if (!Span((ulong)services, (ulong)sizeof(EfiBootServices), 8) ||
                !Excluded((ulong)services, (ulong)sizeof(EfiBootServices), s, scratch, retained) ||
                !Apart((ulong)table, (ulong)sizeof(EfiSystemTable), (ulong)services, (ulong)sizeof(EfiBootServices))) return false;
            delegate* unmanaged<EfiGuid*, void*, void**, ulong> locate = services->LocateProtocol;
            if (!Span((ulong)locate, 1, 1) || !Excluded((ulong)locate, 1, s, scratch, retained) ||
                !Apart((ulong)locate, 1, (ulong)table, (ulong)sizeof(EfiSystemTable)) ||
                !Apart((ulong)locate, 1, (ulong)services, (ulong)sizeof(EfiBootServices))) return false;
            for (int i = 0; i < sizeof(State); i++) if (((byte*)s)[i] != 0) return false;
            for (int i = 0; i < 64; i++)
                if (ReadByte(scratch->Data + i) != 0 || ReadByte(retained->Data + i) != 0) return false;
            // No rejected admission above changes state, guards or payloads.
            scratch->Before0 = retained->Before0 = Guard0;
            scratch->Before1 = retained->Before1 = Guard1;
            scratch->After0 = retained->After0 = Guard1;
            scratch->After1 = retained->After1 = Guard0;
            s->SystemTable = table; s->BootServices = services; s->Locate = locate;
            s->Scratch = scratch; s->Retained = retained; s->Phase = 1;
            return true;
        }

        [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
        internal static byte ReadByte(byte* address) => *address;

        internal static bool Guards(Buffer* b) =>
            b->Before0 == Guard0 && b->Before1 == Guard1 &&
            b->After0 == Guard1 && b->After1 == Guard0;
        internal static bool Zero(byte* bytes, int start, int count)
        {
            for (int i = start; i < start + count; i++) if (ReadByte(bytes + i) != 0) return false;
            return true;
        }
        private static bool Fail(State* s, ulong error)
        { s->Error = error; s->Phase = 4; return false; }

        internal static bool Acquire(State* s)
        {
            if (s->Phase != 1 || s->LocateCalls != 0 || s->RngCalls != 0 || s->PublishedBytes != 0) return false;
            EfiGuid guid;
            guid.Data1 = 0x3152BCA5; guid.Data2 = 0xEADE; guid.Data3 = 0x433D;
            guid.Data4_0 = 0x86; guid.Data4_1 = 0x2E; guid.Data4_2 = 0xC0; guid.Data4_3 = 0x1C;
            guid.Data4_4 = 0xDC; guid.Data4_5 = 0x29; guid.Data4_6 = 0x1F; guid.Data4_7 = 0x44;
            s->Phase = 2; s->LocateCalls = 1;
            s->LocateStatus = s->Locate(&guid, null, (void**)&s->Rng);
            if (s->LocateStatus != 0)
            {
                if (!FailureStorageIntact(s)) return Fail(s, 6);
                return Fail(s, s->LocateStatus == NotFound ? 2UL : 3UL);
            }
            Protocol* rng = s->Rng;
            if (!Span((ulong)rng, (ulong)sizeof(Protocol), 8) ||
                !Excluded((ulong)rng, (ulong)sizeof(Protocol), s, s->Scratch, s->Retained) ||
                !Apart((ulong)rng, (ulong)sizeof(Protocol), (ulong)s->SystemTable, (ulong)sizeof(EfiSystemTable)) ||
                !Apart((ulong)rng, (ulong)sizeof(Protocol), (ulong)s->BootServices, (ulong)sizeof(EfiBootServices)) ||
                !Apart((ulong)rng, (ulong)sizeof(Protocol), (ulong)&guid, (ulong)sizeof(EfiGuid))) return Fail(s, 4);
            delegate* unmanaged<Protocol*, EfiGuid*, nuint, byte*, ulong> get = rng->GetRng;
            if (!Span((ulong)get, 1, 1) || !Excluded((ulong)get, 1, s, s->Scratch, s->Retained) ||
                !Apart((ulong)get, 1, (ulong)rng, (ulong)sizeof(Protocol)) ||
                !Apart((ulong)get, 1, (ulong)s->SystemTable, (ulong)sizeof(EfiSystemTable)) ||
                !Apart((ulong)get, 1, (ulong)s->BootServices, (ulong)sizeof(EfiBootServices))) return Fail(s, 4);
            s->GetRng = get; s->RngCalls = 1;
            s->RngStatus = get(rng, null, (nuint)RequestedBytes, s->Scratch->Data);
            if (s->RngStatus != 0)
            {
                if (!FailureStorageIntact(s)) return Fail(s, 6);
                return Fail(s, 5);
            }
            return Retain(s);
        }

        private static bool FailureStorageIntact(State* s) =>
            Guards(s->Scratch) && Guards(s->Retained) &&
            Zero(s->Scratch->Data, 32, 32) && Zero(s->Retained->Data, 0, 64);

        internal static bool Retain(State* s)
        {
            if (s->Phase != 2 || s->LocateCalls != 1 || s->LocateStatus != 0 ||
                s->RngCalls != 1 || s->RngStatus != 0 || s->PublishedBytes != 0) return false;
            Buffer* scratch = s->Scratch; Buffer* retained = s->Retained;
            if (!Guards(scratch) || !Guards(retained) || !Zero(scratch->Data, 32, 32) ||
                !Zero(retained->Data, 0, 64)) return Fail(s, 6);
            for (int i = 0; i < 32; i++)
            {
                byte value = ReadByte(scratch->Data + i);
                retained->Data[i] = value;
                if (ReadByte(retained->Data + i) != value) return Fail(s, 7);
                scratch->Data[i] = 0;
                if (ReadByte(scratch->Data + i) != 0 || ReadByte(retained->Data + i) != value) return Fail(s, 7);
            }
            if (!Zero(scratch->Data, 0, 64) || !Zero(retained->Data, 32, 32) ||
                !Guards(scratch) || !Guards(retained)) return Fail(s, 7);
            s->PublishedBytes = RequestedBytes; s->Phase = 3;
            return true;
        }

        // Public completion state only; never classify failure scratch bytes for output.
        internal static ulong ClearedBytes(State* s) =>
            s->Phase == 3 && s->PublishedBytes == RequestedBytes ? RequestedBytes : 0;

        internal static bool Run(EfiSystemTable* table, EfiSimpleTextOutputProtocol* console, EfiSerialIoProtocol* serial)
        {
            Token(console, serial, 0);
            fixed (State* s = &s_state)
            fixed (Buffer* scratch = &s_scratch)
            fixed (Buffer* retained = &s_retained)
            {
                if (!Begin(s, scratch, retained, table)) { Token(console, serial, 1); return false; }
                bool success = Acquire(s);
                Token(console, serial, 2); WriteUnsignedDecimal(console, serial, s->LocateStatus);
                Token(console, serial, 3); WriteUnsignedDecimal(console, serial, s->LocateCalls);
                Token(console, serial, 4); WriteUnsignedDecimal(console, serial, s->LocateStatus == 0 && s->Rng != null ? 1UL : 0UL);
                WriteCrLf(console, serial);
                Token(console, serial, 5); WriteUnsignedDecimal(console, serial, s->RngStatus);
                Token(console, serial, 3); WriteUnsignedDecimal(console, serial, s->RngCalls);
                Token(console, serial, 6);
                Token(console, serial, 7); WriteUnsignedDecimal(console, serial, s->PublishedBytes);
                Token(console, serial, 8); WriteUnsignedDecimal(console, serial, ClearedBytes(s));
                Token(console, serial, 9); WriteUnsignedDecimal(console, serial, Guards(scratch) && Guards(retained) ? 64UL : 0UL);
                Token(console, serial, 10); WriteUnsignedDecimal(console, serial, Zero(scratch->Data, 32, 32) && Zero(retained->Data, 32, 32) ? 64UL : 0UL);
                Token(console, serial, 11); WriteUnsignedDecimal(console, serial, s->Phase == 3 ? 1UL : 0UL);
                WriteCrLf(console, serial);
                if (success) { Token(console, serial, 12); return true; }
                if (s->Error == 2) Token(console, serial, 18);
                Token(console, serial, s->Error == 2 ? 13 : s->Error == 3 ? 14 : s->Error == 4 ? 15 : s->Error == 5 ? 16 : 17);
                return false;
            }
        }
        private static void Packed(EfiSimpleTextOutputProtocol* console, EfiSerialIoProtocol* serial, ulong word, int count)
        { for (int i = 0; i < count; i++) { Write(console, serial, (byte)word); word >>= 8; } }
        private static void Token(EfiSimpleTextOutputProtocol* console, EfiSerialIoProtocol* serial, int token)
        {
            switch (token)
            {
                case 0: // TEST_START m03.003.efi\r\n
                    Packed(console, serial, 0x4154535F54534554UL, 8);
                    Packed(console, serial, 0x302E33306D205452UL, 8);
                    Packed(console, serial, 0x0A0D6966652E3330UL, 8);
                    return;
                case 1: // TEST_FAIL m03.003.efi admission\r\n
                    Packed(console, serial, 0x4941465F54534554UL, 8);
                    Packed(console, serial, 0x30302E33306D204CUL, 8);
                    Packed(console, serial, 0x6461206966652E33UL, 8);
                    Packed(console, serial, 0x0D6E6F697373696DUL, 8);
                    Packed(console, serial, 0x000000000000000AUL, 1);
                    return;
                case 2: // M03_ENTROPY_DISCOVERY status=
                    Packed(console, serial, 0x52544E455F33304DUL, 8);
                    Packed(console, serial, 0x435349445F59504FUL, 8);
                    Packed(console, serial, 0x747320595245564FUL, 8);
                    Packed(console, serial, 0x0000003D73757461UL, 5);
                    return;
                case 3: //  calls=
                    Packed(console, serial, 0x003D736C6C616320UL, 7);
                    return;
                case 4: //  found=
                    Packed(console, serial, 0x003D646E756F6620UL, 7);
                    return;
                case 5: // M03_ENTROPY_ACQUIRE status=
                    Packed(console, serial, 0x52544E455F33304DUL, 8);
                    Packed(console, serial, 0x555143415F59504FUL, 8);
                    Packed(console, serial, 0x7461747320455249UL, 8);
                    Packed(console, serial, 0x00000000003D7375UL, 3);
                    return;
                case 6: //  requested=32\r\n
                    Packed(console, serial, 0x7473657571657220UL, 8);
                    Packed(console, serial, 0x000A0D32333D6465UL, 7);
                    return;
                case 7: // M03_ENTROPY_RETAIN bytes=
                    Packed(console, serial, 0x52544E455F33304DUL, 8);
                    Packed(console, serial, 0x415445525F59504FUL, 8);
                    Packed(console, serial, 0x7365747962204E49UL, 8);
                    Packed(console, serial, 0x000000000000003DUL, 1);
                    return;
                case 8: //  scratchCleared=
                    Packed(console, serial, 0x6863746172637320UL, 8);
                    Packed(console, serial, 0x3D64657261656C43UL, 8);
                    return;
                case 9: //  guards=
                    Packed(console, serial, 0x3D73647261756720UL, 8);
                    return;
                case 10: //  tails=
                    Packed(console, serial, 0x003D736C69617420UL, 7);
                    return;
                case 11: //  published=
                    Packed(console, serial, 0x6873696C62757020UL, 8);
                    Packed(console, serial, 0x00000000003D6465UL, 3);
                    return;
                case 12: // CLROS_M03_003_READY bytes=32\r\nTEST_PASS m03.003.efi\r\n
                    Packed(console, serial, 0x304D5F534F524C43UL, 8);
                    Packed(console, serial, 0x45525F3330305F33UL, 8);
                    Packed(console, serial, 0x6574796220594441UL, 8);
                    Packed(console, serial, 0x45540A0D32333D73UL, 8);
                    Packed(console, serial, 0x20535341505F5453UL, 8);
                    Packed(console, serial, 0x2E3330302E33306DUL, 8);
                    Packed(console, serial, 0x0000000A0D696665UL, 5);
                    return;
                case 13: // TEST_FAIL m03.003.efi source_unavailable\r\n
                    Packed(console, serial, 0x4941465F54534554UL, 8);
                    Packed(console, serial, 0x30302E33306D204CUL, 8);
                    Packed(console, serial, 0x6F73206966652E33UL, 8);
                    Packed(console, serial, 0x616E755F65637275UL, 8);
                    Packed(console, serial, 0x656C62616C696176UL, 8);
                    Packed(console, serial, 0x0000000000000A0DUL, 2);
                    return;
                case 14: // TEST_FAIL m03.003.efi discovery_failed\r\n
                    Packed(console, serial, 0x4941465F54534554UL, 8);
                    Packed(console, serial, 0x30302E33306D204CUL, 8);
                    Packed(console, serial, 0x6964206966652E33UL, 8);
                    Packed(console, serial, 0x5F797265766F6373UL, 8);
                    Packed(console, serial, 0x0A0D64656C696166UL, 8);
                    return;
                case 15: // TEST_FAIL m03.003.efi invalid_interface\r\n
                    Packed(console, serial, 0x4941465F54534554UL, 8);
                    Packed(console, serial, 0x30302E33306D204CUL, 8);
                    Packed(console, serial, 0x6E69206966652E33UL, 8);
                    Packed(console, serial, 0x6E695F64696C6176UL, 8);
                    Packed(console, serial, 0x0D65636166726574UL, 8);
                    Packed(console, serial, 0x000000000000000AUL, 1);
                    return;
                case 16: // TEST_FAIL m03.003.efi source_failed\r\n
                    Packed(console, serial, 0x4941465F54534554UL, 8);
                    Packed(console, serial, 0x30302E33306D204CUL, 8);
                    Packed(console, serial, 0x6F73206966652E33UL, 8);
                    Packed(console, serial, 0x6961665F65637275UL, 8);
                    Packed(console, serial, 0x0000000A0D64656CUL, 5);
                    return;
                case 17: // TEST_FAIL m03.003.efi retention_failed\r\n
                    Packed(console, serial, 0x4941465F54534554UL, 8);
                    Packed(console, serial, 0x30302E33306D204CUL, 8);
                    Packed(console, serial, 0x6572206966652E33UL, 8);
                    Packed(console, serial, 0x5F6E6F69746E6574UL, 8);
                    Packed(console, serial, 0x0A0D64656C696166UL, 8);
                    return;
                case 18: // M03_ENTROPY_UNAVAILABLE retainedUnchanged=1 published=0 rngCalls=0\r\n
                    Packed(console, serial, 0x52544E455F33304DUL, 8);
                    Packed(console, serial, 0x56414E555F59504FUL, 8);
                    Packed(console, serial, 0x20454C42414C4941UL, 8);
                    Packed(console, serial, 0x64656E6961746572UL, 8);
                    Packed(console, serial, 0x65676E6168636E55UL, 8);
                    Packed(console, serial, 0x6C62757020313D64UL, 8);
                    Packed(console, serial, 0x20303D6465687369UL, 8);
                    Packed(console, serial, 0x736C6C6143676E72UL, 8);
                    Packed(console, serial, 0x000000000A0D303DUL, 4);
                    return;
            }
        }
    }
