            OS.Kernel.Diagnostics
                .OwnedGDTTSSGeneratedAuditedCSharpStubBytes
                .ValidateReadBack(
                    codePage,
                    codeAddress,
                    M02OwnedGdtTssTerminalPageSize,
                    context,
                    dataAddress,
                    M02OwnedGdtTssTerminalPageSize);

