            public ulong AllocateCodeStatus, AllocateDataStatus, FreeCodeStatus, FreeDataStatus;
            public ulong Code, CodeCapacity, Data, DataCapacity, Image, ImageBytes;
            public M02CheckedPortIoFunctionPointerIntegrationResult Binding;
            public OS.Kernel.Diagnostics.Com1OwnedPortIoBackend Backend;
            public OS.Kernel.Diagnostics.UnexpectedVectorPanicRequest Request;
        }

        internal static void Run(EfiSimpleTextOutputProtocol* console,
            EfiSerialIoProtocol* serial, EfiBootServices* services)
        {
            if (s_authority.State != 0) { Failure(console, serial); Spin(); }
            s_authority.State = 1;
            ulong c = 0, d = 0;
            bool allocatedC = false, allocatedD = false;
            s_authority.AllocateCodeStatus = s_authority.AllocateDataStatus = ~0UL;
            s_authority.FreeCodeStatus = s_authority.FreeDataStatus = ~0UL;
