            { FailBeforeEntry(console, serial, services, c, allocatedC, d, allocatedD, (ulong)image, imageBytes, binding.PageAddress, observationAddress, scratchAddress, selectorsAddress); Spin(); }
            s_authority.AllocationAttemptMask |= 2;
            s_authority.AllocateDataStatus = services->AllocatePages(0, 2, 7, &d);
            allocatedD = s_authority.AllocateDataStatus == 0;
