    private static bool M02Ud2VectorStateRangesOverlap(
        ulong firstAddress,
        ulong firstByteCount,
        ulong secondAddress,
        ulong secondByteCount)
    {
        return OS.Kernel.Diagnostics
            .DisabledDefaultUd2VectorStatePreTerminalContract
            .RangesOverlap(
                firstAddress,
