    private static void WriteUnsignedDecimal(
        EfiSimpleTextOutputProtocol* console,
        EfiSerialIoProtocol* serial,
        ulong value)
    {
        if (value >= 10)
        {
            WriteUnsignedDecimal(console, serial, value / 10);
        }

        Write(console, serial, (byte)((value % 10) + (byte)'0'));
    }
}

